// ---- AUTO-VÉRIFICATION D'ATTRIBUTION ----
function parseKW(s){var m=String(s||'').match(/(\d{2,3})\s*kW/i);return m?parseInt(m[1],10):null;}
function kwNums2(s){return (String(s||'').match(/\d{2,3}(?=\s*kW)/gi)||[]).map(Number);}
function powerOverlap2(a,b){var A=kwNums2(a),Bv=kwNums2(b);if(!A.length||!Bv.length)return true;
 var lo1=Math.min.apply(null,A),hi1=Math.max.apply(null,A),lo2=Math.min.apply(null,Bv),hi2=Math.max.apply(null,Bv);
 return lo1<=hi2+5&&lo2<=hi1+5;}
var GROUPS=[['vw','volkswagen','audi','seat','skoda','cupra','porsche','vag'],['peugeot','citroen','ds','opel','vauxhall'],['fiat','jeep','dodge','ram','chrysler','alfa romeo','lancia','stellantis','opel'],['renault','dacia','alpine'],['hyundai','kia','genesis'],['toyota','lexus'],['honda','acura'],['nissan','infiniti','mitsubishi'],['ford','lincoln'],['chevrolet','gmc','cadillac','buick'],['bmw','mini'],['mercedes','mercedes-benz','smart'],['volvo','polestar','geely','lynk & co','zeekr'],['mg','saic','maxus','roewe'],['byd','denza'],['great wall','haval','wey','tank'],['chery','exeed','omoda'],['jaguar','land rover','tata'],['tesla'],['mazda'],['subaru'],['suzuki'],['nio'],['xpeng'],['li auto','seres','aito'],['changan'],['vinfast'],['fisker'],['rivian'],['lucide','lucid','lucida']];
function grpOf(b){var n=seNorm(b);for(var i=0;i<GROUPS.length;i++){for(var j=0;j<GROUPS[i].length;j++){var g=seNorm(GROUPS[i][j]);if(g===n||n.indexOf(g)===0||g.indexOf(n)===0)return i;}}return -1;}
function brandMatch(rb,qb){var a=seNorm(rb),b=seNorm(qb);if(!a||!b)return false;if(a.indexOf(b)>=0||b.indexOf(a)>=0)return true;var ga=grpOf(a.split('/')[0]),gb=grpOf(b);if(ga>=0&&ga===gb){for(var i=0;i<GROUPS[ga].length;i++){var g=seNorm(GROUPS[ga][i]);if(a.indexOf(g)>=0&&b.indexOf(g)>=0)return true;}}return false;}
function verifyAttribution(r,sel){var warns=[];var level='générique';sel=sel||{};
 var bm=seNorm(r.brand||''),rm=seNorm(r.models||''),rmot=seNorm((r.motor||'')+' '+(r.models||''));
 var generic=/multi|tous|doctrine|retex multi/i.test(bm+rm);
 if(sel.brand){if(generic)level='générique';else if(brandMatch(r.brand,sel.brand))level='exact';else warns.push('marque');}
 if(sel.model){var t=seNorm(sel.model).split(/[\s/]+/)[0];if(!(generic&&level==='générique')){if(rm.indexOf(t)>=0)level='exact';else warns.push('modèle');}}
 if(sel.motor){var t2=seNorm(sel.motor).split(/[\s/]+/)[0];if(t2&&rmot.indexOf(t2)>=0)level=(level==='exact'?'exact':'partiel');else if(!generic)warns.push('motorisation');}
 if(sel.power&&r.power&&r.power!=='-'&&!powerOverlap2(r.power,sel.power))warns.push('puissance');
 var en=r.energy||'',sub=r.subsys||'';
 if(en==='ev'&&['egr','dpf','adblue','turbo','belt'].indexOf(sub)>=0)warns.push('cohérence énergie/sous-système');
 if(en==='lpg'&&sub==='range')warns.push('cohérence');
 if(sel.motor&&/diesel|dci|tdi|bluehdi|multijet/i.test(sel.motor)&&sub==='range')warns.push('cohérence motorisation');
 if(sel.motor&&/bev|[eé]lectrique/i.test(sel.motor)&&['egr','dpf','adblue','turbo','belt'].indexOf(sub)>=0)warns.push('cohérence motorisation');
 return{level:warns.length?'partiel':level,warns:warns};}
function auditAttribution(){var bad=0;var cats=Object.keys(VEHICLE_CATALOG);
 for(var i=0;i<RECALLS.length;i++){var r=RECALLS[i];var b=seNorm(String(r.brand||'').split('/')[0]);
  if(b&&!/multi|tous/.test(b)&&cats.indexOf(b)<0&&grpOf(b)<0){bad++;console.warn('Attribution à vérifier :',r.id,r.brand);}}
 console.log('✅ Audit attribution : '+bad+' entrée(s) hors catalogue (feed/génériques acceptés)');return bad;}
