function renderElroqGrid(sub,q){var g=document.getElementById('elroqGrid');if(!g)return;
 var toks=seNorm(q||'').split(/[\s,]+/).filter(function(t){return t.length>1;});
 var l=ELROQ.filter(function(x){if(sub&&sub!=='Tous'&&x.subsys!==sub)return false;
  if(!toks.length)return true;var hay=seNorm(x.cause+' '+x.mech+' '+x.idx+' '+x.subsys);
  return toks.every(function(t){return hay.indexOf(t)>=0;});});
 g.innerHTML=l.map(function(x){return '<div class="cause-card"><span class="category-badge">'+(ELQ_LBL[x.subsys]||x.subsys)+'</span><span class="badge-src">'+esc15(x.src)+'</span><h3>'+esc15(x.cause.replace(/^\[ELROQ [A-Z]+\] /,''))+'</h3><p class="cause-desc"><strong>Cause :</strong> '+esc15(x.mech.split('→')[0])+'</p><p class="cause-desc"><strong>Mécanisme :</strong> '+esc15(x.mech)+'</p><p class="identification"><strong>Diagnostic :</strong> '+esc15(x.idx)+'</p>'+veRow(x.photos)+'</div>';}).join('')||'<p class="no-results">Aucun symptôme Elroq</p>';
 var c=document.getElementById('elqCount');if(c)c.textContent=l.length+' symptôme(s)/panne(s) Elroq sur '+ELROQ.length;
 var ch=document.getElementById('elroqChips');if(ch)ch.innerHTML=['Tous','charge','range','batt','elec','software','camera','adas','mech','leak','safety'].map(function(s){return '<button class="nav-btn '+(s===sub?'active':'')+'" data-elq="'+s+'">'+(ELQ_LBL[s]||s)+'</button>';}).join('');}
